// Returns the section name for a given mile marker
function currentSection(mile) {
  for (const s of ROUTE_SECTIONS) {
    if (mile >= s.start && mile <= s.end) return s.name;
  }
  return '';
}

// Interpolates a [lat, lng] position on the route for a given mile
function latLngForMile(mile) {
  if (mile <= 0)                 return [ROUTE_WAYPOINTS[0].lat,    ROUTE_WAYPOINTS[0].lng];
  if (mile >= ROUTE_TOTAL_MILES) return [ROUTE_WAYPOINTS.at(-1).lat, ROUTE_WAYPOINTS.at(-1).lng];
  for (let i = 1; i < ROUTE_WAYPOINTS.length; i++) {
    const prev = ROUTE_WAYPOINTS[i - 1];
    const curr = ROUTE_WAYPOINTS[i];
    if (mile <= curr.mile) {
      const t = (mile - prev.mile) / (curr.mile - prev.mile);
      return [
        prev.lat + t * (curr.lat - prev.lat),
        prev.lng + t * (curr.lng - prev.lng),
      ];
    }
  }
  return [ROUTE_WAYPOINTS.at(-1).lat, ROUTE_WAYPOINTS.at(-1).lng];
}
